def main():
    out = Path(__file__).with_name("dev.jsonl")
    rows = []
    for i, (context, message, label, ok, domain, trap, why) in enumerate(ITEMS, 1):
        rows.append({"id": f"d{i:03d}", "context": context, "message": message, "label": label, "ok": ok,
                     "domain": domain, "trap": trap, "why": why})
    out.write_text("\n".join(json.dumps(r, ensure_ascii=False) for r in rows) + "\n", encoding="utf-8")
    from collections import Counter
    print(len(rows), Counter(r["label"] for r in rows), Counter(r["trap"] for r in rows))
    print("words in long_light:", [len(r["message"].split()) for r in rows if r["trap"] == "long_light"])


if __name__ == "__main__":
    main()
